window.docContents[163].resolve({"/Viewing-the-Output/#A-Textbook--Viewing-the-Output":{"contents":"Verso's HTML doesn't presently work correctly when opened directly in a browser, so it should be served via a server.This is due to security restrictions on retrieved files: some of the code hovers are deduplicated to a JSON file that's fetched on demand.\nOne portable way to do this is documented in the root of this repository.\n\n","context":"A Textbook","header":"6. Viewing the Output","id":"/Viewing-the-Output/#A-Textbook--Viewing-the-Output"}});